CREATE OR REPLACE FUNCTION public.icash_prepare_discovery_inventory(p_account uuid, p_revision uuid, p_page integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;cur record;cached jsonb;n integer:=0;streak integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page or not c.enabled or not c.auto_enabled or c.data_rights_until<=now()
 or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
 or not public.icash_membership_work_allowed(p_account) then return 'inventory_held';end if;
 if exists(select 1 from public.icash_operation_spend where operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and state<>'reserved') then return 'awaiting_reconciliation';end if;
 perform public.icash_expand_inventory_markets(p_account);
 select count(*) into streak from (select queued_properties,returned_properties,duplicate_properties from public.icash_discovery_inventory_receipts where account_id=p_account and revision=p_revision order by created_at desc limit 3) recent
 where queued_properties=0 and returned_properties=duplicate_properties;
 if streak=3 then
  update public.icash_inventory_markets set next_scan_at=greatest(next_scan_at,now()+interval '6 hours') where account_id=p_account and zip=c.zip;
  update public.icash_discovery_configs set exhausted=true where account_id=p_account;
  if public.icash_rotate_inventory_market(p_account) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled) then return 'ready';end if;
 perform public.icash_discovery_filter_state_v2(p_account,p_revision,p_page);
 perform public.icash_targeting_state(p_account,p_revision,p_page);
 if public.icash_targeting_query_context(p_account,p_revision,p_page)->'required'='true'::jsonb then
  return case when public.icash_targeting_query_context(p_account,p_revision,p_page)->'ready'='true'::jsonb then 'ready' else 'inventory_held' end;
 end if;
 if c.research_list_id is not null then return 'ready';end if;
 for cur in select * from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted and public.icash_targeting_cursor_available(p_account,p_revision,zip,strategy) order by strategy for update loop
  loop
   cached:=public.icash_known_assigned_research_page(c.zip,cur.strategy,cur.next_page,c.per_page,
  case when c.research_version in (1,2) then jsonb_build_object('version',case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',null) end);
   exit when cached is null;
   update public.icash_discovery_filter_cursors set next_page=next_page+1,skipped_assigned_pages=skipped_assigned_pages+1,exhausted=not (cached->>'hasNextPage')::boolean
   where account_id=p_account and revision=p_revision and strategy=cur.strategy;
   cur.next_page:=cur.next_page+1;n:=n+1;
   if n>=64 then return 'inventory_advancing';end if;
   exit when not (cached->>'hasNextPage')::boolean;
  end loop;
 end loop;
 if not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted and public.icash_targeting_cursor_available(p_account,p_revision,zip,strategy)) then
  perform public.icash_mark_inventory_empty(p_account,p_revision,p_page);
  if exists(select 1 from public.icash_discovery_configs where account_id=p_account and revision<>p_revision) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 return 'ready';
end $function$

CREATE OR REPLACE FUNCTION public.icash_targeting_query_context(p_account uuid, p_revision uuid, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;q icash_research_private.targeting_query_settings;e icash_research_private.exclusions;
 history boolean;active boolean;ready boolean;required boolean;policy jsonb;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account and revision=p_revision and next_page=p_page;
 if not found then return jsonb_build_object('required',true,'ready',false,'policy',null);end if;
 select * into q from icash_research_private.targeting_query_settings where id=1;
 select * into e from icash_research_private.exclusions where id=1;
 history:=exists(select 1 from public.icash_discovery_filter_pages p where p.zip=c.zip
  and p.plan->>'version'='seller-targeting-v1' and p.state not in ('empty','unavailable'));
 active:=exists(select 1 from icash_research_private.targeting_experiments x where public.icash_targeting_available(p_account,c.zip,x.definition));
 ready:=coalesce(q.enabled and e.state='ready' and e.list_id=q.list_id and e.last_synced_at<=now()
  and e.last_synced_at is not null
  and not exists(select 1 from icash_research_private.exclusion_items where synced_at is null)
  and not exists(select 1 from icash_research_private.targeting_acquired_properties where synced_at is null)
  and not exists(select 1 from public.icash_operation_spend o
   cross join lateral (select array(select known.zip from (
    select fp.zip from public.icash_discovery_filter_pages fp where fp.operation_key=o.operation_key and fp.account_id=o.account_id
    union select public.icash_stalled_search_configuration(o.account_id,o.operation_key)->>'zip'
    union select estimate.query#>>'{locations,0,code}' from icash_research_private.estimates estimate
     where estimate.operation_key=o.operation_key and estimate.account_id=o.account_id
      and jsonb_array_length(case when jsonb_typeof(estimate.query->'locations')='array' then estimate.query->'locations' else '[]'::jsonb end)=1
      and estimate.query->'locations'=jsonb_build_array(jsonb_build_object('type','zip_code','code',estimate.query#>>'{locations,0,code}'))
    union select prior.zip from public.icash_discovery_configs prior where prior.account_id=o.account_id
     and o.operation_key='discovery:'||prior.account_id||':'||prior.revision||':'||prior.next_page
   ) known where known.zip ~ '^[0-9]{5}$') zips) scopes
   where o.operation_key like 'discovery:%' and o.state not in ('settled','cancelled')
    and not (o.operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and o.state='reserved')
    and (cardinality(scopes.zips)=0 or c.zip=any(scopes.zips))),false);
 required:=history or exists(select 1 from icash_research_private.financial_settings where id=1 and enabled);
 if ready and (history or active or required) then policy:=jsonb_build_object('version',case when c.research_version=1 then 'research-efficiency-v1' else 'research-efficiency-v2' end,'exclusionListId',q.list_id);end if;
 if exists(select 1 from icash_research_private.financial_settings where id=1 and enabled) then
  ready:=ready and icash_research_private.financial_capable();
  if ready then policy:=icash_research_private.financial_policy(p_account,p_revision,policy);else policy:=null;end if;
 end if;
 return jsonb_build_object('required',required,'ready',ready and (history or active or required),'policy',policy);
end $function$
